div.script:
$('#nsearch1').submit(function(){
	var key = $('#search-input').val();
	if(key == '' || key == "Tìm kiếm...")
	{
		alert('Mời bạn nhập vào từ khóa tìm kiếm...');
		$('#search-input').focus();
		return false
	}
	//window.location.href= base_url +'tim-kiem/'+encodeURIComponent(key);
	window.location.href = base_url +'tim-kiem/' + encodeURIComponent(key);
	return false; 
});

